from collections import Counter
class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        c1 = Counter(nums1)
        c2 = Counter(v * k for v in nums2)
        ans = 0
        for v, c in c2.items():
            for m in range(v, 10**6 + 1, v):
                ans += c * c1.get(m, 0)
        return ans

