class Solution {
public:
    int numberOfPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        unordered_map<int, long long> c1, c2;
        for (int x : nums1) c1[x]++;
        for (int x : nums2) c2[(long long)x * k]++;
        long long ans = 0;
        for (auto& [v, c] : c2)
            for (long long m = v; m <= 1000000; m += v) {
                auto it = c1.find((int)m);
                if (it != c1.end()) ans += c * it->second;
            }
        return (int)ans;
    }
};

