class Solution {
    public int numberOfPairs(int[] nums1, int[] nums2, int k) {
        Map<Integer, Long> c1 = new HashMap<>(), c2 = new HashMap<>();
        for (int x : nums1) c1.merge(x, 1L, Long::sum);
        for (int x : nums2) c2.merge(x * k, 1L, Long::sum);
        long ans = 0;
        for (var e : c2.entrySet())
            for (int m = e.getKey(); m <= 1000000; m += e.getKey()) {
                Long c = c1.get(m);
                if (c != null) ans += e.getValue() * c;
            }
        return (int) ans;
    }
}

