        c2 = Counter(v * k for v in nums2)
        ans = 0
        for x, cx in c1.items():
            d = 1
            while d * d <= x:
                if x % d == 0:
                    ans += cx * c2.get(d, 0)
                    e = x // d
                    if e != d:
                        ans += cx * c2.get(e, 0)
                d += 1
        return ans

