            int x = en.getKey(); long cx = en.getValue();
            for (int d = 1; (long) d * d <= x; d++)
                if (x % d == 0) {
                    Long a = c2.get(d); if (a != null) ans += cx * a;
                    int e = x / d;
                    if (e != d) { Long b = c2.get(e); if (b != null) ans += cx * b; }
                }
        }
        return (int) ans;
    }
}

